if (n == 0) {
    return block{nullptr, 0};
}

size_t space = max_size - (p - data);
if (space < n) {
    return block{nullptr, 0};
}

void* aligned_ptr = std::align(alignment, n, reinterpret_cast<void*&>(p), space);
if (!aligned_ptr) {
    return block{nullptr, 0};
}

char* result = static_cast<char*>(aligned_ptr);
p = result + n;

return block{result, n};
// END_CODE

